def insignia(vb: int = 300) -> Tela:
    c = Tela("lobo_sombrio_2-insignia", vb)
    sem = P.Semente(20261010)
    
    # ── Materiais (Shaders S-Rank) ──────────────
    # Exemplo: vc pode substituir cores solidas pelos shaders
    # f_glow = c.brilho("glow", 4, 1.3)
    
    # O vtracer gera as coords originais da imagem. Precisamos descobrir a escala.
    # Ex: se a imagem era 1024x1024, k = vb / 1024.0
    # O desenvolvedor precisa definir esse 'k' baseado na resolucao da imagem base.
    # Vamos prever k=300/1024 = 0.293 se a geracao da IA foi 1024x1024.
    k = vb / 1024.0  
    
    import re
    P_SVG = _paths_extraidos()
    
    main = c.camada("main", z=1)
    
    for fill_orig, d_orig in P_SVG:
        # Escala as coordenadas do path
        d_scaled = re.sub(r'[\d.]+', lambda m: str(round(float(m.group(0)) * k, 1)), d_orig)
        
        # Ignora fundo preto ou muito escuro (ajuste se necessário)
        if fill_orig.lower() in ["#000000", "#010101", "#020202", "#030303", "#131010", "#0a0a0a", "#111111", "#121212", "#0f0f0f", "#141414"]:
            continue
        main.add(f'<path d="{d_scaled}" fill="{fill_orig}" stroke="none" />')
            
    # Adicione particulas aqui...
            
    return c


